{"query":"query LegacyObservedAdsQuery(
  $limit: Int = 150
  $offset: Int
) {
  clientCompatibleObservedAds(limit: $limit, offset: $offset) {
    data {
      _nodeId
      id
      business
      category {
        id
        type
        _nodeId
      }
      contact {
        chat
        courier
        name
        negotiation
        phone
      }
      created_time
      delivery {
        rock {
          active
          mode
          offer_id
        }
      }
      description
      external_url
      last_refresh_time
      location {
        city {
          id
          name
          normalized_name
          _nodeId
        }
        district {
          id
          name
          normalized_name
          _nodeId
        }
        region {
          id
          name
          normalized_name
          _nodeId
        }
      }
      map {
        lat
        lon
        radius
        show_detailed
        zoom
      }
      omnibus_pushup_time
      params {
        key
        name
        type
        value {
          __typename
          ... on GenericParam {
            key
            label
          }
          ... on CheckboxesParam {
            label
            checkboxParamKey: key
          }
          ... on PriceParam {
            value
            type
            negotiable
            label
            currency
            converted_value
            converted_currency
            arranged
            budget
          }
          ... on SalaryParam {
            from
            to
            arranged
            converted_currency
            converted_from
            converted_to
            currency
            gross
            type
          }
          ... on ErrorParam {
            message
          }
        }
      }
      partner {
        code
      }
      photos {
        link
        height
        rotation
        width
      }
      promotion {
        highlighted
        top_ad
        options
        premium_ad_page
        b2c_ad_page
      }
      protect_phone
      safedeal {
        allowed_quantity
        weight_grams
      }
      shop {
        subdomain
      }
      status
      title
      url
      user {
        id
        uuid
        _nodeId
        about
        b2c_business_page
        banner_desktop
        banner_mobile
        company_name
        created
        is_online
        last_seen
        logo
        logo_ad_page
        name
        other_ads_enabled
        photo
        seller_type
        social_network_account_type
      }
      valid_to_time
    }
    metadata {
      total_elements
    }
  }
}
